arguments:
{"script":"mkdir -p files_list && cat > files_list/count_extension.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")"
[ "$#" -eq 2 ] || { echo "Usage: $0 <list_file> <extension>" >&2; exit 1; }
list_file=$1
ext=$2
[ -f "$list_file" ] || { echo "File not found: $list_file" >&2; exit 1; }
[[ "$ext" =~ ^\.[a-z]{3}$ ]] || { echo "Invalid extension: $ext" >&2; exit 1; }
grep -cE "${ext//./\\.}$" "$list_file"
EOF
chmod +x files_list/count_extension.sh && printf 'a.txt\nb.jpg\nc.txt\n' > files_list/example_list.txt && ./files_list/count_extension.sh example_list.txt .txt"}

